using System;using System.Linq;using UnityEngine.InputSystem;
public sealed partial class TrainingInputConfig {
 public ModifiedInputAction[] modifier1Actions={ModifiedInputAction.Record,ModifiedInputAction.Throw,ModifiedInputAction.Force,ModifiedInputAction.Reset,ModifiedInputAction.Play,ModifiedInputAction.Dash,ModifiedInputAction.None,ModifiedInputAction.None,ModifiedInputAction.None};
 public ModifiedInputAction[] modifier2Actions=new ModifiedInputAction[9];
 public string modifier1Binding="<Gamepad>/leftTrigger",modifier2Binding="";
 public string[] slotGamepadBindings={"<Gamepad>/buttonWest","<Gamepad>/buttonNorth","<Gamepad>/rightShoulder","<Gamepad>/buttonSouth","<Gamepad>/buttonEast","<Gamepad>/rightTrigger","","",""};
 public string trcGamepadBinding="<Gamepad>/leftShoulder";
 public string[] extraKeyboardBindings={"","",""},secondExtraKeyboardBindings={"","",""};
 public string[] SlotKeys(bool second){var baseKeys=second?new[]{secondWeakPKeyboardBinding,secondMediumPKeyboardBinding,secondStrongPKeyboardBinding,secondWeakKKeyboardBinding,secondMediumKKeyboardBinding,secondStrongKKeyboardBinding}:new[]{firstWeakPKeyboardBinding,firstMediumPKeyboardBinding,firstStrongPKeyboardBinding,firstWeakKKeyboardBinding,firstMediumKKeyboardBinding,firstStrongKKeyboardBinding};return baseKeys.Concat(second?secondExtraKeyboardBindings:extraKeyboardBindings).ToArray();}
 public bool ValidateV3(out string error){error=null;if(modifier1Actions==null||modifier1Actions.Length!=9||modifier2Actions==null||modifier2Actions.Length!=9){error="Nine modifier action entries required";return false;}foreach(var a in modifier1Actions.Concat(modifier2Actions))if(!Enum.IsDefined(typeof(ModifiedInputAction),a)){error="Invalid modifier action";return false;}if(slotGamepadBindings==null||slotGamepadBindings.Length!=9){error="Nine pad slots required";return false;}foreach(var group in new[]{SlotKeys(false),SlotKeys(true),slotGamepadBindings.Concat(new[]{trcGamepadBinding}).ToArray()}){var used=new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var path in group){if(string.IsNullOrWhiteSpace(path))continue;if(!path.StartsWith("<")||path.IndexOf(">/",StringComparison.Ordinal)<2){error="Use InputSystem <Device>/control paths";return false;}if(!used.Add(path.Trim())){error="Duplicate binding/chord trigger in context";return false;}}}var normal=SlotKeys(false).Concat(SlotKeys(true)).Concat(slotGamepadBindings).Concat(new[]{trcGamepadBinding,"<Keyboard>/leftShift","<Keyboard>/rightShift","<Keyboard>/leftCtrl","<Keyboard>/rightCtrl","<Keyboard>/i","<Keyboard>/space","<Keyboard>/r","<Keyboard>/p","<Keyboard>/escape","<Gamepad>/start",firstMoveDpadGamepadBinding,firstMoveStickGamepadBinding}).ToArray();if(!ModifierPressOwnership.ValidateBindings(modifier1Binding,modifier2Binding,normal,out error))return false;
  foreach(var device in InputSystem.devices){foreach(var group in new[]{SlotKeys(false),SlotKeys(true),slotGamepadBindings.Concat(new[]{trcGamepadBinding}).ToArray()}){var used=new System.Collections.Generic.HashSet<InputControl>();foreach(var path in group){if(string.IsNullOrWhiteSpace(path))continue;var control=InputControlPath.TryFindControl(device,path);if(control!=null&&!used.Add(control)){error="Aliases duplicate a binding/chord trigger";return false;}}}if(!string.IsNullOrWhiteSpace(modifier1Binding)&&!string.IsNullOrWhiteSpace(modifier2Binding)){var a=InputControlPath.TryFindControl(device,modifier1Binding);var b=InputControlPath.TryFindControl(device,modifier2Binding);if(a!=null&&a==b){error="T1 and T2 resolve to the same control";return false;}}}
  foreach(var device in InputSystem.devices)foreach(var m in new[]{modifier1Binding,modifier2Binding})if(!string.IsNullOrEmpty(m)){var control=InputControlPath.TryFindControl(device,m);if(control!=null&&normal.Any(path=>!string.IsNullOrEmpty(path)&&InputControlPath.TryFindControl(device,path)==control)){error="Modifier aliases a normal device control";return false;}}return true;
 }
}
